function zip(keys, values, locale) {
  if (values.length !== keys.length || values.some(value => typeof value !== 'string' || !value.trim())) throw Error(`DUSTWAKE_COPY_SHAPE:${locale}:${values.length}/${keys.length}`);
  return Object.fromEntries(keys.map((key,index)=>[key,values[index]]));
}
export const COPY = Object.freeze(Object.fromEntries(LOCALES.map(locale=>[locale,Object.freeze({...zip(KEYS,UI[locale],locale),...zip(NOTICE_KEYS,NOTICES[locale],locale)})])));
export const TEXT_KEYS = Object.freeze([...KEYS,...NOTICE_KEYS]);
export function text(locale,key,vars={}) {
  if(key==='title')return title(locale);
  const aliases={comingSoon:'coming',saveWarning:'saveError',storageFailure:'saveError',noWebGL:'graphicsError',loadingError:'graphicsError',recover:'reload',purchaseConfirm:'confirm',purchaseBody:'purchaseBody',padChoice:'choosePad',success:'win',failure:'lose'};
  if(key==='progress')return `${text(locale,'stage')} ${vars.stage??vars.n??1} / ${vars.total??60}`;
  const resolved=aliases[key]||key;
  const value=EXTRA_COPY[locale]?.[resolved] ?? COPY[locale]?.[resolved] ?? GUIDE_COPY[locale]?.[resolved];
  if(typeof value!=='string')throw Error(`DUSTWAKE_MISSING_COPY:${locale}:${key}`);
  return value.replace(/\{([a-zA-Z]+)\}/g,(whole,name)=>vars[name]===undefined?whole:String(vars[name]));
}
export function title(locale) {
  if(!LOCALES.includes(locale))throw Error(`DUSTWAKE_LOCALE:${locale}`);
  return globalThis.window?.WEIGHTPLAY_GAME_TITLES?.[GAME_ID]?.[locale] || TITLE_MAP[locale];
}
export const notice = (locale,code,vars={}) => code ? text(locale,code,vars) : '';
export const escapeHtml = value => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');

