const LAYOUT_INDEX={O:0,R:1,V:2,U:3,H:4,Z:5,C:6,T:7,K:8};
const STAGE_NAMES_HANS=['苔径初扫','东端亮点','石边分路','北园一圈','双袋开园','雨痕第一刷','干湿两岸','苔石转角','短袋混扫','干袋先行','错模式绕路','长墙湿带','双口石庭','交错小堆','湿区双程','风口初见','南门捷径','风后湿尘','东风回廊','三拍风门','中庭绕吹','南袋北刷','湿带接力','北风小货','回站灯窗','先远后近','双岸小环','干道换袋','风回双湿','曙光总清理','第一座分站','转角补给','墙外回运','双湿分站','一次落位','小口压舱','湿舱留空','双闸外袋','斜庭回压','三袋封单','风外双湿','中线汇流','晚到北站','湿门小堆','风停出货','回字湿庭','长墙双货','之字压舱','中庭五群','晚亮分站','南岸留袋','风桥远单','雨后双院','短窗北行','四角零散','双墙收尾','风口两刷','隔岸大单','雨庭循环','尘光重开'];
export function stageCopy(locale,stage) {
  const t=(key,vars)=>text(locale,key,vars),rules=stage.rules||{},total=(stage.dust||[]).reduce((sum,item)=>sum+item.count,0),details=[t('completeAll',{n:total}),t('seconds',{n:stage.seconds})];
  if(rules.maxTrips)details.push(t('maxTrips',{n:rules.maxTrips}));
  if(rules.minLoad)details.push(t('minLoad',{n:rules.minLoad}));
  if(rules.dryDeliveredBeforeWet)details.push(t('dryFirst',{n:rules.dryDeliveredBeforeWet}));
  if(rules.depotWindow){const w=rules.depotWindow;details.push(t('depotWindow',{open:w.openSeconds??w.open??3,closed:w.closedSeconds??w.closed??3}));}
  if(rules.portableRequired)details.push(t('portableRequired'));
  if(rules.portableUnlockAfterBaseLoad)details.push(t('baseUnlock',{n:rules.portableUnlockAfterBaseLoad}));
  if(rules.gateUnlockAfterBaseDelivered)details.push(t('gateUnlock',{n:rules.gateUnlockAfterBaseDelivered}));
  const gate=stage.gates?.[0];if(gate)details.push(t('windWindow',{open:gate.openSeconds,closed:gate.closedSeconds}));
  const name=locale==='en'?stage.name:locale==='zh-Hant'?stage.nameZh:locale==='zh-Hans'?STAGE_NAMES_HANS[stage.id-1]:null;
  const starGoals=Array.isArray(stage.starSeconds)?t('starGoals',{three:stage.starSeconds[0],two:stage.starSeconds[1]}):'';
  if(starGoals)details.splice(2,0,starGoals);
  return {title:name||`${LAYOUTS[locale][LAYOUT_INDEX[stage.layout]??0]} · ${stage.id}`,chapter:t(stage.chapter===2?'chapterTwo':'chapterOne'),summary:starGoals||details[2]||details[0],primaryGoal:details[0],starGoals,details};
}

