export function renderStaticGuide(locale){
  const i=LOCALES.indexOf(locale);if(i<0)throw Error(`DUSTWAKE_LOCALE:${locale}`);
  const t=key=>escapeHtml(text(locale,key)),gameTitle=escapeHtml(title(locale));
  const sections=[['goalHeading','goal'],['howHeading','how'],['rulesHeading','rules'],['finishHeading','finish'],['strategyHeading','strategy'],['saveHeading','saveInfo'],['designHeading','design']];
  const questions=['Full','Wet','Depot','Press','Tools','Skin'];
  return `<section id="gameGuide" lang="${locale}" class="game-page-info game-page-info-static" data-wp-main-guide data-wp-game-guide data-wp-game-owned-guide="true" data-wp-guide-renderer="copy.mjs#renderStaticGuide" data-runtime-localize="off"><div class="game-info-title"><h2 data-runtime-localize="off">${gameTitle}</h2></div><div class="game-info-tags"><span>${t('cleaningTag')}</span><span>${t('routeTag')}</span><span>${t('simulationTag')}</span></div><div class="game-info-facts"><div class="game-info-fact"><strong>${t('stages')}</strong><span>60</span></div><div class="game-info-fact"><strong>${t('chapter')}</strong><span>2</span></div><div class="game-info-fact"><strong>${t('equipment')}</strong><span>3 · ${t('free')}</span></div><div class="game-info-fact"><strong>${t('cosmetic')}</strong><span>${t('permanent')}</span></div></div><div class="game-info-sections">${sections.map(([heading,body])=>`<section class="game-info-section"><h3>${t(heading)}</h3><p>${t(body)}</p></section>`).join('')}</div><section class="game-info-faq"><h3>${t('faqHeading')}</h3>${questions.map(key=>`<details><summary>${t('faq'+key+'Q')}</summary><p>${t('faq'+key+'A')}</p></details>`).join('')}</section><section class="game-info-section game-info-related-section" data-wp-guide-related-interface="9"><h3>${t('relatedHeading')}</h3><div class="game-info-related">${RELATED.map(item=>{const name=globalThis.window?.WEIGHTPLAY_GAME_TITLES?.[item.id]?.[locale]||item.names[i];return `<a class="game-info-related-card" data-game-id="${item.id}" href="/${ROUTES[i]}/games/${item.id}/"><span class="game-info-related-poster"><img src="${item.poster}" alt="${escapeHtml(name)}" width="320" height="320" loading="lazy" decoding="async"></span><span class="game-info-related-copy"><strong data-runtime-localize="off">${escapeHtml(name)}</strong></span></a>`;}).join('')}</div></section></section>`;
}

export function localizeShell(source,locale){
  const i=LOCALES.indexOf(locale);if(i<0)throw Error(`DUSTWAKE_LOCALE:${locale}`);
  const lang=LOCALES[i],route=ROUTES[i],url=`https://weightplay.com/${route}/games/${GAME_ID}/`,official=title(locale),esc=escapeHtml;
  let html=source.replace(/<html\b[^>]*>/i,`<html lang="${lang}" dir="${locale==='ar'?'rtl':'ltr'}" data-wp-official-name>`);
  html=html.replace(/(<([a-z][\w-]*)\b[^>]*\bdata-copy="([^"]+)"[^>]*>)[^<]*(<\/\2>)/gi,(_all,open,_tag,key,close)=>open+esc(text(locale,key))+close);
  html=html.replace(/<[^>]*\bdata-copy-(aria|alt)="([^"]+)"[^>]*>/gi,(tag,kind,key)=>{const attribute=kind==='aria'?'aria-label':'alt',value=esc(text(locale,key)),pattern=new RegExp(`(\\s${attribute}=")[^"]*(")`,'i');return pattern.test(tag)?tag.replace(pattern,(_match,before,after)=>before+value+after):tag.replace(/>$/,` ${attribute}="${value}">`);});
  html=html.replace(/<title>[^<]*<\/title>/i,`<title>${esc(official)} | WeightPlay</title>`);
  html=html.replace(/<a\b[^>]*\bdata-lobby-link\b[^>]*>/gi,tag=>tag.replace(/href="[^"]*"/i,`href="/${route}/?preview=1"`));
  html=html.replace(/(<p\b[^>]*id="mainProgress"[^>]*>)[^<]*(<\/p>)/i,`$1${esc(text(locale,'stage'))} 1 / 60$2`);
  html=html.replace(/(<span\b[^>]*data-dustwake-stat-label="([^"]+)"[^>]*>)[^<]*(<\/span>)/gi,(_all,open,key,close)=>open+esc(text(locale,key))+close);
  html=html.replace(/<option\b[^>]*value="([^"]+)"[^>]*>/gi,(tag,value)=>{const out=tag.replace(/\sselected(?:="[^"]*")?/i,'');return value===locale?out.replace(/>$/,' selected>'):out;});
  for(const field of ['description','og:description','twitter:description']){const pattern=new RegExp(`(<meta\\b[^>]*(?:name|property)="${field}"[^>]*content=")[^"]*(")`,'i');html=html.replace(pattern,(_all,before,after)=>before+esc(text(locale,'summary'))+after);}
  for(const field of ['og:title','twitter:title']){const pattern=new RegExp(`(<meta\\b[^>]*(?:name|property)="${field}"[^>]*content=")[^"]*(")`,'i');html=html.replace(pattern,(_all,before,after)=>before+esc(official)+after);}
  html=html.replace(/(<meta\b[^>]*property="og:url"[^>]*content=")[^"]*(")/i,(_all,before,after)=>before+url+after);
  html=html.replace(/(<link\b[^>]*rel="canonical"[^>]*href=")[^"]*(")/i,(_all,before,after)=>before+url+after);
  html=html.replace(/<script\s+type="application\/ld\+json">[\s\S]*?<\/script>/i,()=>`<script type="application/ld+json">${JSON.stringify({"@context":"https://schema.org","@type":"VideoGame",name:official,url,image:`https://weightplay.com/games/${GAME_ID}/art/poster.webp`,description:text(locale,'summary'),inLanguage:locale,operatingSystem:'Web browser',applicationCategory:'Game',isAccessibleForFree:true,publisher:{'@type':'Organization',name:'WeightStudio'}}).replaceAll('<','\\u003c')}</script>`);
  return html;
}
